use std::error::Error;
fn parse_port(text: &str) -> Result<u16, std::num::ParseIntError> {
    let port = text.parse()?;
    Ok(port)
}
fn main() -> Result<(), Box<dyn Error>> {
    let port = parse_port("8080")?;
    println!("{port}");
    Ok(())
}

fn parse_port(text: &str) -> Result<u16, std::num::ParseIntError> {
    text.parse()
}
fn main() {
    match parse_port("not-a-port") {
        Ok(port) => println!("{port}"),
        Err(_) => println!("invalid port"),
    }
}
